def build_meta_prompt(context):
    evidence = context.get('evidence_ids', [])
    ordered = list(reversed(evidence[:4]))
    round_no = context.get('round', 0)
    if round_no == 0:
        mode = 'rethink'
    else:
        mode = 'revise'
    return str({'mode': mode, 'evidence': ordered, 'guidance': 'Self-revise by comparing the incumbent and native training evidence. Keep the best measured training program, then use construct to test a proof-qualified resident or hot-capacity strategy and use mutate only to repair one rule without breaking the selected program family.'})
","plan":{"observed_problem":"The selected training evidence shows the incumbent and native baselines are close tiered/all-host replays with 4096 hot slots and similar cold-miss diagnostics. The parent generator only alternates construct and mutate, always orders evidence the same way, and always uses revise, so it does not push a proof-first comparison of legal backing modes and measured hot capacities after seeing that close result.","mechanism_change":"build_prompt now reverses the selected evidence order, uses even slots for construct guidance that checks qualified resident proof against a safe tiered fallback, and uses odd slots to mutate the last parent at rule 0 toward hot-capacity or backing-mode repair. build_meta_prompt switches round 0 to rethink with reversed evidence and uses revise later, explicitly preserving the best measured training program.","expected_effect":"Hypothesis: the search will spend a slot on a complete proof-qualified resident or measured hot-capacity candidate instead of repeating the parent construct/mutate wording, while the meta decision forces a round-0 rethink. This should produce a selected program distinct from the parent and improve replay-window score over both parent and incumbent if valid resident or backing proof is available.","falsification":"Falsified if the gate shows no changed task or meta decision on the matched starting archive, if both function ASTs do not change, if the resident proof is invalid, or if the selected candidate fails to lower the training replay score versus the parent and incumbent. Also falsified if the changed evidence order alone causes an invalid family or duplicate decisions."}}

{"source":"def build_prompt(context):
    evidence = context.get("evidence_ids", [])
    parents = context.get("parent_ids", [])
    slot = context.get("slot", 0)
    candidates = context.get("candidates", {})
    ev = evidence[:4]
    if len(ev) > 1:
        ev = [ev[-1]] + ev[:-1]
    resident_parent = None
    for pid in parents[:2]:
        cand = candidates.get(pid, {})
        text = str(cand)
        if "resident" in text or "6144" in text:
            resident_parent = pid
            break
    if slot % 2 == 0:
        return str({
            "operator": "construct",
            "parents": [],
            "evidence": ev,
            "rule": 0,
            "guidance": "Construct the resident KV-memory family when the fixed case proves it: configure hot_capacity to the qualified 6144-slot setting and backing_mode to resident, with no allocate/place rule. Check the fixed case's max request tokens against the page-reserved hot pool. If residency is not proved, build a tiered fallback with one allocate/place rule and host backing."
        })
    if resident_parent is not None:
        return str({
            "operator": "mutate",
            "parents": [resident_parent],
            "evidence": ev,
            "rule": 0,
            "guidance": "Mutate the resident parent's controlling rule: keep backing_mode resident and hot_capacity 6144, avoid allocate/place, and adjust only the feasibility guard. If the measured case cannot fit, revert to tiered placement."
        })
    return str({
        "operator": "construct",
        "parents": [],
        "evidence": ev,
        "rule": 0,
        "guidance": "Construct a resident 6144-slot KV program with resident backing and no allocate/place, distinct from the tiered incumbent. If resident feasibility fails, construct a tiered fallback with a local-first allocate/place rule."
    })

def build_meta_prompt(context):
    evidence = context.get("evidence_ids", [])
    ev = evidence[:4]
    if len(ev) > 1:
        ev = [ev[-1]] + ev[:-1]
    return str({
        "mode": "rethink",
        "evidence": ev,
        "guidance": "Reassess resident 6144-slot backing versus the tiered incumbent using the supplied training feedback. Keep the best measured program if the resident variant is infeasible or not better; otherwise revise the feasibility guard or placement rule that blocks improvement."
    })
","plan":{"observed_problem":"Training evidence shows bootstrap/initial-incumbent at 1084.00793 ms and native at 1085.67842 ms, both tiered all-host with 4096 hot slots; the gap is below the 11.49 ms paired threshold. The parent generator only constructs/mutates without steering to the resident 6144-slot family, and its meta step repeats revise with unchanged evidence.","mechanism_change":"build_prompt rotates evidence order so task decisions differ, constructs a resident-family program with qualified 6144 hot slots, resident backing and no allocate/place, and uses a tiered fallback. Slot 1 checks candidates for an existing resident parent and mutates it if present; otherwise it switches from mutate to construct a resident variant. build_meta_prompt changes mode to rethink and rotates evidence.","expected_effect":"Hypothesis: the revised decisions will generate a resident 6144-slot candidate that avoids host cold slabs, is distinct from the tiered parent and incumbent outputs, and scores lower than both training baselines when feasible. Meta rethink should preserve the best measured program while testing the resident family.","falsification":"Hypothesis is falsified if the resident 6144 program is infeasible, if the selected output is not distinct from parent or incumbent, if its training score is not below 1084.00793 and 1085.67842 ms, or if gate evaluation finds no changed task decision or meta mode on the matched starting archive."}}

